from concurrent.futures import ThreadPoolExecutor


def run_one(call):
    result = {"type": "tool_result", "tool_use_id": call.id}
    try:
        result["content"] = check_health(call.input["service"])
    except TimeoutError:  # a result for Claude, not a crash
        result["is_error"] = True
        result["content"] = "Timed out after 5 s. Report it as unknown."
    return result


def handle_tools(reply):
    calls = [b for b in reply.content if b.type == "tool_use"]
    with ThreadPoolExecutor() as pool:  # independent, read-only checks
        results = list(pool.map(run_one, calls))  # keeps the call order
    messages.append({"role": "user", "content": results})  # one user turn
    return client.messages.create(
        model="claude-opus-5-5", max_tokens=4096,
        tools=TOOLS, messages=messages,
    )


